/* SportMatch — inlined photos for design-tool exports.
   Same patch as photo-data.js, resized to 1100px / q86 — enough resolution for
   full-bleed swipe cards on retina displays. */
(function () {
  var DATA = {"basketball-aerial":"data:image/jpeg;base64,","basketball-bw":"data:image/jpeg;base64,","football-match":"data:image/jpeg;base64,","football-sunset":"data:image/jpeg;base64,","streetball-bw":"data:image/jpeg;base64,","tennis-clay":"data:image/jpeg;base64,","tennis-net":"data:image/jpeg;base64,"};
  function keyOf(s) { var m = String(s).match(/([^\/?#]+)\.jpg(?:[?#]|$)/); return m && m[1]; }
  function patch() {
    var img = window.SM_IMG;
    if (!img || img.__inlined) return !!img;
    var orig = img.url.bind(img);
    img.url = function (k) { var r = orig(k); return DATA[keyOf(r)] || DATA[k] || r; };
    img.__inlined = true;
    return true;
  }
  if (!patch()) { var n = 0, iv = setInterval(function () { if (patch() || ++n > 80) clearInterval(iv); }, 30); }
})();
